-- ============ A3. THE 376mm IS CIRCULAR ============
UPDATE evidence_sources SET
  notes = notes || ' || ADVERSARIAL FINDING 2026-07-26 - THE 376mm SEAT-DEPTH FIGURE IS CIRCULAR AND MUST NOT BE READ AS CORROBORATION. REF-00953 writes: "Jean has a buttock to popliteal length of 376 mm ... Kothiyal and Tettey recommend 376 mm for both office and bus seating, exactly right for Jean." Both halves trace to the SAME 171-person Sydney dataset (REF-00963/00964): the percentile and the recommendation are one number appearing twice. "Exactly right for Jean" is therefore a tautology, not an independent match. REF-00953 does not claim otherwise, but a reader - me, in batch 3 - could easily take it as two data points, and the corpus should record that it is one.',
  updated_at='2026-07-26', updated_by_session='session_2026-07-26-energy-conservation-rest-points-seating-adversarial'
WHERE ref_id='REF-00953';

